// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] calldata _tos, uint256 v) public {
        // 1. Restrict to admissible domain: at least one recipient
        vm.assume(_tos.length > 0);
        // 2. Deploy a failing callee that always reverts on a low-level call.
        //    This provides the adversarial external party the fuzzer cannot synthesize from a raw address.
        FailingCallee failing = new FailingCallee();
        // 3. Drive the reference transfer through the failing callee.
        //    If any transferFrom sub-call fails, the reference contract must revert.
        //    The buggy version skips the require(_s) and always succeeds, returning true.
        bool referenceReverted = false;
        try c.transfer(from, address(failing), _tos, v) {
            // if we reach here, the call did not revert
        } catch {
            referenceReverted = true;
        }
        // 4. Assert that the reference ALWAYS reverts (since every sub-call to the failing callee reverts).
        //    The buggy contract would not revert and would return true, failing this assertion.
        assertTrue(referenceReverted);
    }
}

contract FailingCallee {
    fallback() external payable {
        revert("FailingCallee: forced revert");
    }
}
